import {readFile} from 'node:fs/promises';
import Ajv2020 from 'ajv/dist/2020.js';
import addFormats from 'ajv-formats';
const root='/home/enpasos/projects/skillpilot';
const r=root+'/curricula/DE/Gymnasium/quality/goal-evidence/2026-10-19/chemie-current455-F03-one-native-description-inputs-technical-20261019-v1/current-f03/round-b';
const batch='chemie-current455-f03-one-D-20261019-v1-first-pass-b.batch-001';
const bytes=await readFile(r+'/results/'+batch+'.records.jsonl');
if (bytes.includes(13)||bytes.at(-1)!==10) throw new Error('Records require real terminal LF and no CR');
const lines=bytes.toString('utf8').split('\n');
if(lines.length!==2||lines[1]!==''||!lines[0]) throw new Error('Exactly one real JSONL record required');
const record=JSON.parse(lines[0]);
const schema=JSON.parse(await readFile(r+'/contracts/goal-description-review-record.schema.json','utf8'));
if(schema.additionalProperties!==false)throw new Error('Closed record schema expected');
const ajv=new Ajv2020({allErrors:true});addFormats(ajv);
const validate=ajv.compile(schema);if(!validate(record))throw new Error(ajv.errorsText(validate.errors));
const runSchema=JSON.parse(await readFile(root+'/contracts/goal-evidence/v1/goal-evidence-ai-run-manifest.schema.json','utf8'));
if(runSchema.additionalProperties!==false)throw new Error('Closed run schema expected');
const validateRun=ajv.compile(runSchema);const run=JSON.parse(await readFile(r+'/results/'+batch+'.run.json','utf8'));if(!validateRun(run))throw new Error(ajv.errorsText(validateRun.errors));
console.log(JSON.stringify({realTerminalLF:true,noCR:true,exactlyOneRecord:true,jsonParse:true,recordClosedSchema:true,runClosedSchema:true,recordStatus:record.recordStatus,reviewAuthority:record.reviewAuthority}));
